use vstd::prelude::*;

verus! {

fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> (result: Vec<f32>)
    requires
        true,
    ensures
        result@.len() == arr@.len() + values@.len(),
        forall|i: int|
            0 <= i < arr@.len() ==>
                result@[i] == arr@[i],
        forall|j: int|
            0 <= j < values@.len() ==>
                result@[arr@.len() + j] == values@[j],
{
    let mut result: Vec<f32> = Vec::new();

    let arr_len = arr.len();
    let values_len = values.len();

    let mut i: usize = 0;
    while i < arr_len
        invariant
            result@.len() == i as int,
            arr@.len() == arr_len as int,
            values@.len() == values_len as int,
            forall|k: int| 0 <= k < i as int ==> result@[k] == arr@[k],
        decreases (arr_len - i),
    {
        result.push(arr[i]);
        i = i + 1;
    }

    let mut j: usize = 0;
    while j < values_len
        invariant
            result@.len() == arr_len as int + j as int,
            arr@.len() == arr_len as int,
            values@.len() == values_len as int,
            forall|k: int| 0 <= k < arr_len as int ==> result@[k] == arr@[k],
            forall|t: int| 0 <= t < j as int ==> result@[arr_len as int + t] == values@[t],
        decreases (values_len - j),
    {
        result.push(values[j]);
        j = j + 1;
    }

    result
}

} // verus!

